import {KEY,fresh,restore,investigated,xp,level,collect,checkFinale,finishRoom} from './adventure-state.js';
import {project,inside,moveToward} from './navigation.js';
const $=s=>document.querySelector(s),app=$('#app'),panel=$('#panel'),panelContent=$('#panel-content');
let book,course,campaign,dialogues={rooms:[]},extras={rooms:[]},activeSpot=null,state,actor={x:.5,y:.85},goal=null,arrival=null,activeBeat=null,activeCard=null,selectedTool=null,selectedClue=null,verb='look',lastFrame=0,finalView=null,npcTopic=null,npcFollow=null;
let timer,dragged=null,audio;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clean=s=>{const d=new DOMParser().parseFromString(String(s??''),'text/html');d.querySelectorAll('script,iframe,object,embed,style,link').forEach(n=>n.remove());d.querySelectorAll('*').forEach(n=>[...n.attributes].forEach(a=>{if(a.name.startsWith('on')||a.value.startsWith('javascript:'))n.removeAttribute(a.name);}));return d.body.innerHTML;};
const sig={arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',book:'<path d="M12 5v15M3 4c4-1 6 0 9 2 3-2 5-3 9-2v14c-4-1-6 0-9 2-3-2-5-3-9-2Z"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3Zm6-3v15m6-12v15"/>',tool:'<path d="m14 7-7 7a3 3 0 0 0 4 4l7-7M14 7a5 5 0 0 1 6-5l-3 3 2 2 3-3a5 5 0 0 1-4 7"/>',check:'<path d="m5 12 4 4 10-10"/>',bag:'<path d="M5 8h14l2 12H3Zm3 0V6a4 4 0 0 1 8 0v2"/>',talk:'<path d="M4 4h16v12H9l-5 4Zm4 5h8m-8 3h5"/>',settings:'<path d="M4 7h16M4 17h16M8 4v6m8 4v6"/>'};
const icon=k=>`<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${sig[k]||sig.book}</svg>`;
const button=(label,act,cls='btn-primary',attrs='')=>`<button class="btn ${cls}" data-act="${act}" ${attrs}>${label}</button>`;
const rooms=[
{name:'De noodcentrale',image:'assets/room-dispatch.webp',floor:[[.25,.57],[.77,.57],[.82,.95],[.23,.95]],points:[[.11,.35,.28,.65],[.7,.29,.66,.62],[.95,.69,.77,.73],[.53,.16,.5,.59],[.85,.08,.72,.58]],tool:[.9,.54,.77,.75]},
{name:'Het ontvangstdepot',image:'assets/room-depot.webp',floor:[[.25,.54],[.77,.54],[.81,.95],[.23,.95]],points:[[.12,.49,.28,.69],[.63,.39,.63,.59],[.89,.54,.77,.73],[.32,.17,.38,.57],[.81,.31,.74,.56]],tool:[.32,.17,.37,.57]},
{name:'De keten achter de zending',image:'assets/room-depot.webp',floor:[[.25,.54],[.77,.54],[.81,.95],[.23,.95]],points:[[.63,.39,.63,.59],[.32,.17,.38,.57],[.89,.54,.77,.73],[.12,.49,.28,.69],[.81,.31,.74,.56]],tool:[.32,.17,.37,.57]},
{name:'De reparatiewerkplaats',image:'assets/chapter-1.webp',floor:[[.25,.5],[.85,.5],[.9,.69],[.23,.69]],points:[[.15,.5,.28,.61],[.43,.72,.48,.67],[.65,.38,.68,.58],[.84,.62,.83,.65],[.8,.3,.75,.55]],tool:[.38,.79,.45,.68]},
{name:'De kamer van de spelregels',image:'assets/chapter-3.webp',floor:[[.11,.82],[.93,.82],[.97,.97],[.05,.97]],points:[[.2,.61,.23,.87],[.66,.23,.65,.85],[.84,.34,.83,.86],[.59,.73,.6,.91],[.08,.42,.15,.86]],tool:[.1,.78,.25,.87]},
{name:'De etalage van morgen',image:'assets/chapter-5.webp',floor:[[.44,.48],[.77,.48],[.9,.7],[.55,.7]],points:[[.17,.3,.46,.54],[.43,.77,.55,.67],[.6,.39,.62,.55],[.85,.35,.78,.61],[.5,.25,.55,.51]],tool:[.79,.79,.74,.64]}
].map(r=>({...r,floor:r.floor.map(([x,y])=>({x,y}))}));
const tools=[{id:'meter',name:'Stroommeter',cell:0,room:0,detail:'Met de stroommeter lees je de capaciteit van de noodaccu. Gebruik hem op het noodpaneel voordat je de stroom verdeelt.'},{id:'map',name:'Ketenkaart',cell:1,room:1,detail:'Deze kaart verbindt de zending aan locaties en partijen in de keten. Je hebt hem nodig om het spoor van de batterij te volgen.'},{id:'key',name:'Servicesleutel',cell:2,room:3,detail:'Met deze sleutel open je de instellingen van de machine. Wat de machine wel en niet meeneemt, wordt zo zichtbaar.'},{id:'camera',name:'Onderzoekscamera',cell:3,room:0,detail:'Bewaar wat je ziet. De camera helpt je bevindingen vast te leggen in het onderzoeksboek.'},{id:'ledger',name:'Grootboek',cell:4,room:4,detail:'Het grootboek houdt bezit, opbrengsten en investeringen naast elkaar. Gebruik het bij je reconstructie van macht.'},{id:'lens',name:'Inspectielens',cell:5,room:5,detail:'Deze lens helpt je een claim uit elkaar te halen: welk deel zie je, welk geheel wordt ermee gesuggereerd?'}];
const allBeats=()=>book.chapters[0].investigations.flatMap(i=>i.beats);
const inv=()=>book.chapters[0].investigations[state.room];
const cfg=()=>rooms[state.room];
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notify('Browseropslag is niet beschikbaar. Exporteer je onderzoeksboek via Instellingen.');}}
function notify(text){clearTimeout(timer);$('#toast').textContent=text;$('#toast').classList.add('visible');$('#announcements').textContent=text;timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function sound(){if(state.muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();[440,554,659].forEach((f,n)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+n*.09;o.frequency.value=f;g.gain.setValueAtTime(.03,t);g.gain.exponentialRampToValueAtTime(.001,t+.4);o.connect(g).connect(audio.destination);o.start(t);o.stop(t+.4);});}catch{}}
function toolSprite(t){return `<span class="tool-sprite" style="background-position:${[0,50,100][t.cell%3]}% ${t.cell<3?0:100}%" aria-hidden="true"></span>`;}
function header(){return `<header class="topbar"><button class="brand" data-act="home"><span class="brand-mark">O</span><span><span class="brand-name">Onder de oppervlakte</span><small>Les 1 · Economie & systemen</small></span></button><nav aria-label="Spelnavigatie"><button class="nav-link" data-act="route">${icon('map')}<span class="nav-label">Route</span></button><button class="nav-link" data-act="knowledge">${icon('book')}<span class="nav-label">Naslag</span></button><button class="nav-link" data-act="settings">${icon('settings')}<span class="nav-label">Bewaren</span></button><div class="level"><div class="level-badge"><span>${level(state)}</span></div><div><strong>Level ${level(state)}</strong><small>${xp(state)} XP · ${state.beats.length} inzichten</small></div></div></nav></header>`;}
function render(){activeSpot=null;activeBeat=null;activeCard=null;goal=null;arrival=null;app.innerHTML=state.started?`<div class="adventure-shell">${header()}${world()}</div>`:`${header()}${landing()}`;if(state.started){actor=project(actor,cfg().floor);positionActor();}}
function landing(){return `<main class="hero" id="main"><div class="hero-art" style="background-image:url('assets/room-dispatch.webp')" role="img" aria-label="De noodcentrale van NOVA bij zonsondergang"></div><div class="hero-copy"><p class="eyebrow">NOVA · Het tweede leven</p><h1>De stroom<br><em>valt uit.</em></h1><p class="lead">Morgen lanceert NOVA een nieuwe telefoon.<br>Vanavond is er niet genoeg stroom voor iedereen.</p><p class="lead">Verken de kamers. Spreek de mensen.<br>Verzamel gereedschap en ontdek wat er achter de belofte zit.</p><div class="hero-actions">${button((state.beats.length?'Ga verder met je avontuur':'Stap de noodcentrale binnen')+' '+icon('arrow'),'start')}${button('Bekijk de route','route','btn-quiet')}</div><div class="intro-meta"><span>${icon('bag')} Voorwerpen gebruiken</span><span>${icon('talk')} Vragen & doorvragen</span></div></div><div class="hero-foot"><div><p>Les 1 · Economie en systemen</p><p>Onderzoeken → verbanden leggen → eindpuzzel</p></div><div><p class="image-caption">Een adventure in ontwikkeling</p><p>Je onderzoeksboek reist met je mee.</p></div></div></main>`;}
function world(){const c=cfg(),i=inv(),done=i.beats.filter(b=>state.beats.includes(b.id)).length;return `<main class="adventure-main" id="main"><section class="world-side"><div class="world-heading"><div><p class="eyebrow">NOVA · ${state.room+1} / 6 · ${esc(i.title)}</p><h1>${esc(c.name)}</h1></div><span class="room-location">${state.rooms.includes(i.id)?'Verbanden gelegd':`${done} / ${i.beats.length} onderzocht`}</span></div><div class="world-viewport"><div class="walk-scene" id="walk-scene" tabindex="0" role="region" aria-label="Bestuur je onderzoeksdrone in ${esc(c.name)} met WASD, pijltjestoetsen of door te klikken"><img class="room-art" src="${c.image}" alt="${esc(c.name)}, een geïllustreerde kamer met onderzoeksvoorwerpen" draggable="false"><div class="room-shade"></div><div class="walk-instructions">Klik om te vliegen · klik op een voorwerp om het te onderzoeken</div><div class="foot-shadow" id="foot-shadow"></div><img id="player" class="actor" src="assets/drone.png" alt="Je onderzoeksdrone" draggable="false">${i.beats.map((b,n)=>{const p=c.points[n%c.points.length],offset=n>=c.points.length?.07:0;return `<button class="room-object ${state.beats.includes(b.id)?'solved':''}" data-act="approach" data-id="${b.id}" style="--spot-x:${p[0]*100}%;left:${p[0]*100}%;top:${(p[1]+offset)*100}%" title="${esc(b.title)}"><span class="object-dot">${state.beats.includes(b.id)?'✓':n+1}</span><span class="object-label">${esc(b.title)}</span></button>`;}).join('')}${toolObject()}${extraObjects()}${npcObject()}<div class="scene-speech" id="scene-speech"><strong>${esc(npc().name)}</strong><span>${esc(npc().opening)}</span></div></div><div id="tray-mount"></div></div><div class="room-controls"><div class="verb-controls"><button class="verb ${verb==='look'?'active':''}" data-act="verb" data-verb="look">Kijken</button><button class="verb ${verb==='use'?'active':''}" data-act="verb" data-verb="use">Gebruiken</button><button class="verb" data-act="npc">${icon('talk')} Praten</button></div><span>WASD / pijltjes · klik om te vliegen</span><div class="exploration-controls"><button data-act="searchSpots" aria-pressed="false">Toon zoekplekken</button><button data-act="help">Hoe werkt dit?</button></div></div><div class="inventory-bar" aria-label="Je gereedschap"><span class="inventory-title">Mijn<br>gereedschap</span>${state.tools.length?state.tools.map(id=>{const t=tools.find(t=>t.id===id);return `<button class="pocket-item ${selectedTool===id?'active':''}" data-act="selectTool" data-id="${id}" title="${esc(t.detail)}">${toolSprite(t)}<span>${esc(t.name)}</span></button>`;}).join(''):'<span class="empty-pocket">Er ligt gereedschap in de kamer. Kijk goed rond.</span>'}</div></section><aside class="notebook" aria-label="Onderzoeksboek"><p class="eyebrow">Persoonlijk veldboek · automatisch bewaard</p><h2>Mijn aanwijzingen</h2><p class="book-subtitle">${esc(i.title)}<br>Verzamel het bewijs. Maak dan de verbinding.</p><div class="notebook-progress">${i.beats.map(b=>`<span class="${state.beats.includes(b.id)?'done':''}"></span>`).join('')}</div><div class="clue-list">${i.beats.map(b=>`<div class="clue-entry ${state.beats.includes(b.id)?'':'locked'}"><span>${state.beats.includes(b.id)?'✓':'○'}</span><div>${state.beats.includes(b.id)?`<button data-act="readClue" data-id="${b.id}" draggable="true" data-clue="${b.id}">${esc(b.clueTitle||b.title)}</button><small>Gevonden · te gebruiken als bewijs</small>`:`${esc(b.clueTitle||b.title)}<small>Nog te onderzoeken</small>`}</div></div>`).join('')}</div><label class="notes-title" for="field-notes">Mijn voorspellingen & verbanden</label><textarea id="field-notes" data-notes="${i.id}" placeholder="Wat verwacht je? Wat veranderde er? Welke aanwijzingen horen bij elkaar?">${esc(state.notes[i.id]||'')}</textarea><span class="save-indicator" id="save-indicator">Notities blijven op dit apparaat.</span>${button(state.rooms.includes(i.id)?'Verbanden opnieuw bekijken':`Breng de puzzelstukken samen ${icon('arrow')}`,'finale','combine-btn',investigated(state,i)?'':'disabled')}<p class="book-footer">${investigated(state,i)?'Alle aanwijzingen zijn onderzocht.':'Eerst alle aanwijzingen onderzoeken.'}</p>${state.rooms.includes(i.id)?button(state.room===5?'De eindpuzzel van les 1':'Open de volgende plek','nextRoom','combine-btn'):''}</aside></main>`;}
function toolObject(){const t=tools.find(t=>t.room===state.room&&!state.tools.includes(t.id));if(!t)return '';const p=cfg().tool;return `<button class="room-object tool-object" data-act="approachTool" data-id="${t.id}" style="--spot-x:${p[0]*100}%;left:${p[0]*100}%;top:${p[1]*100}%"><span class="object-dot">${icon('tool')}</span><span class="object-label">${esc(t.name)}</span></button>`;}
function npc(){return dialogues.rooms.find(r=>r.investigationId===inv().id)?.npc||{name:['Noor','Omar','Mila','Iris','Eva','Lena'][state.room],role:'Onderzoekspartner',opening:inv().beats[0].intro,topics:inv().beats.map(b=>({id:b.id,question:`Wat speelt bij ${b.title.toLowerCase()}?`,answer:b.hint,followups:[{id:'example',question:'Kun je dat verder uitleggen?',answer:b.explainAfter}]}))};}
function extraSpots(){return extras.rooms.find(r=>r.room===state.room)?.spots||[];}
function extraObjects(){return extraSpots().map(x=>`<button class="extra-object ${state.exploration[x.id]?'visited':''}" data-act="approachExtra" data-id="${x.id}" aria-label="Onderzoek ${esc(x.title)}" style="--spot-x:${x.point[0]*100}%;left:${x.point[0]*100}%;top:${x.point[1]*100}%"><span class="extra-dot"></span><span class="extra-label">${esc(x.title)}</span></button>`).join('');}
function approachExtra(id){const x=extraSpots().find(x=>x.id===id);if(!x)return;closeTray();walkTo(...x.approach,()=>{activeSpot=x;renderExtra();});speak(`Ik bekijk ${x.title.toLowerCase()}.`,'Jij');}
function renderExtra(feedback='',answered=false){const x=activeSpot;if(!x)return;const locked=x.requires&&(!state.tools.includes(x.requires)||selectedTool!==x.requires||verb!=='use');state.exploration[x.id]=locked?'locked':'visited';persist();document.querySelector(`[data-act="approachExtra"][data-id="${x.id}"]`)?.classList.add('visited');let body=`<p>${esc(x.observation)}</p>`;if(locked){body+=`<div class="tray-hint">Dit serviceslot past op de servicesleutel. Je kunt later terugkomen met het juiste gereedschap.</div>`;}else{if(x.question&&!answered)body+=`<p>${esc(x.question)}</p><div class="puzzle-cards">${x.options.map((o,n)=>button(esc(o.text),'sideAnswer','puzzle-card',`data-index="${n}"`)).join('')}</div>`;if(x.detail)body+=`<div class="reveal-text"><p>${esc(x.detail)}</p></div>`;if(feedback)body+=`<div class="small-feedback ${answered?'':'retry'}">${esc(feedback)}</div>`;if(!x.question||answered)body+=button(state.tools.includes('camera')?'Leg vast met mijn onderzoekscamera':'Noteer dit zijspoor','saveSide','btn-secondary');}body+=button('Verder zoeken','closeTray','btn-primary');tray(x.title,body,'Een spoor onderzoeken');}
function saveSide(){if(!activeSpot)return;const x=activeSpot,text=x.options?.find(o=>o.correct)?.feedback||x.detail||x.observation,entry=`${x.title}: ${x.observation} ${text}`;if(!(state.notes[inv().id]||'').includes(entry)){state.notes[inv().id]=(state.notes[inv().id]||'')+'\n'+entry;persist();$('#field-notes').value=state.notes[inv().id];}notify('Zijspoor vastgelegd in je onderzoeksboek.');}
function npcPosition(){const positions=[[.34,.76],[.37,.79],[.37,.79],[.31,.63],[.4,.91],[.69,.64]];const [x,y]=positions[state.room];return project({x,y},cfg().floor);}
function npcObject(){const p=npcPosition(),n=npc(),cell=state.room;return `<div class="npc-shadow" style="left:${p.x*100}%;top:${p.y*100}%"></div><button class="world-npc" data-act="approachNPC" aria-label="Praat met ${esc(n.name)}" style="left:${p.x*100}%;top:${p.y*100}%;--npc-sole:${cell<3?95:92}%;background-position:${[0,50,100][cell%3]}% ${cell<3?0:100}%"><span class="npc-label">${esc(n.name)} · ${icon('talk')}</span></button>`;}
function approachNPC(){closeTray();const p=npcPosition();walkTo(p.x+.075,p.y+.025,npcPanel);speak(`Ik vlieg naar ${npc().name}.`,'Jij');}
function speak(text,name=npc().name){const box=$('#scene-speech');if(box){box.innerHTML=`<strong>${esc(name)}</strong><span>${esc(text)}</span>`;box.style.display='block';}$('#announcements').textContent=text;}
function positionActor(){const p=$('#player'),shadow=$('#foot-shadow');if(!p)return;p.style.left=actor.x*100+'%';p.style.top=(actor.y-.11)*100+'%';p.style.transform=`translate(-50%,-50%) rotate(${goal?(actor.facing||1)*5:0}deg) scale(${.83+(actor.y-.55)*.6})`;p.style.zIndex=actor.y<npcPosition().y?'2':'4';shadow.style.left=actor.x*100+'%';shadow.style.top=actor.y*100+'%';}
function walkTo(x,y,callback=null){goal=project({x,y},cfg().floor);arrival=callback;const p=$('#player');p?.classList.add('walking');}
function approach(bid){const b=inv().beats.find(b=>b.id===bid),n=inv().beats.indexOf(b),p=cfg().points[n%cfg().points.length];if(!b)return;closeTray();walkTo(p[2],p[3],()=>openBeat(b));speak(verb==='use'&&selectedTool?`Ik neem de ${tools.find(t=>t.id===selectedTool)?.name.toLowerCase()} mee naar ${b.title.toLowerCase()}.`:`Ik ga ${b.title.toLowerCase()} onderzoeken.`,'Jij');}
function approachTool(id){const t=tools.find(t=>t.id===id),p=cfg().tool;closeTray();walkTo(p[2],p[3],()=>showTool(t));}
function showTool(t){tray(t.name,`<div class="tool-display">${toolSprite(t)}</div><p>${esc(t.detail)}</p>${button('Neem mee','takeTool','btn-primary',`data-id="${t.id}"`)}`,'Een bruikbaar voorwerp');}
function tray(title,body,kicker='Onderzoeken'){const mount=$('#tray-mount');if(!mount)return;mount.innerHTML=`<section class="interaction-tray" aria-label="${esc(title)}"><header class="tray-head"><div><p class="eyebrow">${esc(kicker)}</p><h2>${esc(title)}</h2></div><button class="close" data-act="closeTray" aria-label="Sluit onderzoek">×</button></header><div class="tray-body">${body}</div></section>`;goal=null;arrival=null;$('#player')?.classList.remove('walking');mount.querySelector('.close').focus({preventScroll:true});}
function closeTray(){const m=$('#tray-mount');if(m)m.innerHTML='';activeBeat=null;activeCard=null;}
function requiredTool(b){if(b.simulation==='electricity')return 'meter';if(state.room===2&&b.type==='connect')return 'map';if(state.room===3&&b.type==='build')return 'key';return null;}
function openBeat(b){const required=requiredTool(b);if(required&&!state.tools.includes(required)){speak(`Hiervoor heb ik de ${tools.find(t=>t.id===required).name.toLowerCase()} nodig. Die vind ik ${required==='map'?'bij de routekaart in het vorige depot':'in deze kamer'}.`,'Jij');notify('Zoek het gereedschap en gebruik het bij dit voorwerp.');return;}if(required&&(verb!=='use'||selectedTool!==required)){speak(`Selecteer de ${tools.find(t=>t.id===required).name.toLowerCase()} in je gereedschap en gebruik hem hier.`,'Jij');notify('Klik eerst op het juiste gereedschap en daarna op het voorwerp.');return;}activeBeat=b;activeCard=null;renderBeat();}
function renderBeat(feedback='',passed=false){const b=activeBeat;if(!b)return;const solved=state.beats.includes(b.id)&&!b.replay;let body=`<p>${esc(b.intro)}</p><button class="hint-toggle" data-act="hint">Ik wil een handvat</button><div id="beat-hint"></div>`;
if(solved){body=`<div class="clue-earned"><p class="eyebrow">Bewijs in je onderzoeksboek</p><div class="display">${esc(b.clueTitle||b.title)}</div><p>${esc(b.explainAfter)}</p>${button('Bekijk opnieuw','replayBeat','btn-secondary')}${button('Terug naar de kamer','closeTray')}</div>`;tray(b.title,body,'Aanwijzing gevonden');return;}
if(b.type==='inspect'){const seen=state.seen[b.id]||[];body+=`<div class="inspect-grid">${b.reveal.map((r,n)=>`<button class="inspect-object ${seen.includes(r.id)?'seen':''}" data-act="inspect" data-id="${r.id}"><div class="object-photo" style="background-image:url('${cfg().image}');background-position:${[10,40,70,90][n%4]}% ${[25,60,45,80][n%4]}%"></div><span>${seen.includes(r.id)?'✓ ':''}${esc(r.label)}</span></button>`).join('')}</div><div id="reveal-content"></div>${seen.length===b.reveal.length?button('Bewaar de bevinding','collectBeat'):''}`;}
if(b.type==='sort'){const assignments=state.sorts[b.id]||{};body+=`<p class="puzzle-help">Pak een kaart en leg hem op een plek. Slepen of aanklikken werkt allebei.</p><div class="puzzle-cards">${b.cards.map(c=>`<button class="puzzle-card ${assignments[c.id]?'placed':''} ${activeCard===c.id?'selected':''}" draggable="true" data-card="${c.id}" data-act="selectCard" data-id="${c.id}">${esc(c.text)}</button>`).join('')}</div><div class="drop-zones">${b.categories.map(c=>`<button class="drop-zone" data-drop="${c.id}" data-act="placeCard" data-id="${c.id}"><strong>${esc(c.label)}</strong>${b.cards.filter(p=>assignments[p.id]===c.id).map(p=>`<span class="zone-card">${esc(p.text)}</span>`).join('')}</button>`).join('')}</div>${button('Onderzoek de verbindingen','checkBeat')}`;}
if(b.type==='connect'){const links=state.links[b.id]||{},right=[...b.pairs].sort((a,c)=>a.right.localeCompare(c.right));body+=`<p class="puzzle-help">Kies links een stuk bewijs. Verbind het rechts aan wat erdoor wordt verklaard.</p><div class="board-columns"><div>${b.pairs.map(p=>`<button class="puzzle-card ${activeCard===p.id?'selected':''} ${links[p.id]?'placed':''}" data-act="selectCard" data-id="${p.id}">${esc(p.left)}${links[p.id]?`<br><small>→ ${esc(b.pairs.find(x=>x.id===links[p.id])?.right)}</small>`:''}</button>`).join('')}</div><div>${right.map(p=>`<button class="puzzle-card" data-act="connect" data-id="${p.id}">${esc(p.right)}</button>`).join('')}</div></div>${button('Bekijk of het verband klopt','checkBeat')}`;}
if(b.type==='order'){const order=state.orders[b.id]||[],pool=[...b.order].sort((a,c)=>a.text.localeCompare(c.text));body+=`<p class="puzzle-help">Bouw de keten door kaarten in volgorde toe te voegen. Klik een geplaatste kaart om hem terug te leggen.</p><div class="order-list">${Array.from({length:b.order.length},(_,n)=>`<button class="order-slot" data-act="removeOrder" data-index="${n}" data-orderdrop="${n}"><strong>${n+1}</strong>${order[n]?esc(b.order.find(o=>o.id===order[n])?.text):'Leg hier de volgende stap'}</button>`).join('')}</div><div class="puzzle-cards">${pool.filter(p=>!order.includes(p.id)).map(p=>`<button class="puzzle-card" draggable="true" data-card="${p.id}" data-act="addOrder" data-id="${p.id}">${esc(p.text)}</button>`).join('')}</div>${button('Laat de keten werken','checkBeat')}`;}
if(b.type==='build'){const selected=state.selections[b.id]||[];body+=`<p class="puzzle-help">Kies onderdelen die elkaar aanvullen. Elke ingreep heeft mogelijkheden en grenzen.</p><div class="puzzle-cards">${b.options.map(o=>`<button class="puzzle-card ${selected.includes(o.id)?'selected':''}" data-act="build" data-id="${o.id}">${selected.includes(o.id)?'✓ ':''}${esc(o.text)}</button>`).join('')}</div>${button('Voer mijn ontwerp uit','checkBeat')}`;}
if(b.type==='decision'){body+=`<div class="puzzle-cards">${b.options.map(o=>`<button class="puzzle-card" data-act="decide" data-id="${o.id}">${esc(o.text)}</button>`).join('')}</div>`;}
if(b.type==='experiment')body+=experimentMarkup(b);
if(feedback)body+=`<div class="small-feedback ${passed?'':'retry'}" aria-live="polite">${esc(feedback)}</div>`;
if(passed)body+=button('Bewaar de bevinding '+icon('book'),'collectBeat');
tray(b.title,body,b.type==='experiment'?'Experiment · voorspel, verander, verklaar':b.sceneObject==='person'?'Gesprek · onderzoek een afweging':'Een aanwijzing onderzoeken');if(b.type==='experiment')refreshExperiment();}
function inspect(id){const b=activeBeat,r=b.reveal.find(r=>r.id===id);state.seen[b.id]??=[];if(!state.seen[b.id].includes(id))state.seen[b.id].push(id);persist();renderBeat();$('#reveal-content').innerHTML=`<article class="reveal-text"><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p></article>`;}
function selectCard(id){activeCard=id;document.querySelectorAll('[data-act=selectCard]').forEach(el=>el.classList.toggle('selected',el.dataset.id===id));}
function placeCard(id){if(!activeCard){notify('Kies eerst een kaart.');return;}const b=activeBeat;state.sorts[b.id]??={};state.sorts[b.id][activeCard]=id;activeCard=null;persist();renderBeat();}
function connect(id){if(!activeCard){notify('Kies eerst het bewijs links.');return;}state.links[activeBeat.id]??={};state.links[activeBeat.id][activeCard]=id;activeCard=null;persist();renderBeat();}
function addOrder(id){const b=activeBeat;state.orders[b.id]??=[];if(!state.orders[b.id].includes(id))state.orders[b.id].push(id);persist();renderBeat();}
function checkBeat(){const b=activeBeat;let pass=false,feedback='';if(b.type==='sort'){const a=state.sorts[b.id]||{},wrong=b.cards.filter(c=>a[c.id]!==c.category);pass=!wrong.length;feedback=pass?b.explainAfter:wrong[0].feedback||b.hint;}if(b.type==='connect'){const a=state.links[b.id]||{},wrong=b.pairs.filter(c=>a[c.id]!==c.id);pass=!wrong.length;feedback=pass?b.explainAfter:wrong[0].feedback||b.hint;}if(b.type==='order'){const a=state.orders[b.id]||[],wrong=b.order.find((c,n)=>a[n]!==c.id);pass=!wrong;feedback=pass?b.explainAfter:wrong.feedback||b.hint;}if(b.type==='build'){const a=state.selections[b.id]||[],required=b.required||b.options.filter(o=>o.correct).map(o=>o.id);pass=a.length===required.length&&required.every(id=>a.includes(id));feedback=pass?b.explainAfter:(b.options.find(o=>a.includes(o.id)&&!required.includes(o.id))?.feedback||'Je ontwerp mist nog een onderdeel. '+b.hint);}renderBeat(feedback,pass);}
function decide(id){const b=activeBeat,o=b.options.find(o=>o.id===id);state.choices[b.id]=id;persist();renderBeat(o.feedback,o.correct);}
function collectBeat(){const b=activeBeat;if(!b)return;const repeat=state.beats.includes(b.id);b.replay=false;collect(state,b);persist();sound();render();tray(b.clueTitle||b.title,`<div class="clue-earned"><p class="eyebrow">${repeat?"Aanwijzing opnieuw onderzocht":"Aanwijzing bewaard · +30 XP"}</p><p>${esc(b.explainAfter)}</p><label class="note-label" for="clue-observation">Wat betekent dit voor jouw onderzoek?</label><textarea id="clue-observation" data-notes="${b.id}" placeholder="Een korte observatie in je eigen woorden.">${esc(state.notes[b.id]||'')}</textarea>${button('Terug naar de kamer','closeTray')}</div>`,'In je onderzoeksboek');if(investigated(state,inv()))speak('We hebben nu alle aanwijzingen. Welke verbanden verklaren samen wat er gebeurt?');}
function experimentMarkup(b){const saved=state.expValues[b.id]||{};if(b.simulation==='electricity'){return `<p class="puzzle-help">Voorspel het gevolg. Verdeel daarna de schaarse stroom en voer je plan uit.</p><div class="experiment-controls">${[['production','Productie',60],['repair','Reparatie',40],['emergency','Noodklanten',40]].map(([id,label,max])=>`<label class="power-channel"><span>${label}</span><input type="range" min="0" max="${max}" step="10" value="${saved[id]??(id==='production'?60:20)}" data-exp="${id}" aria-label="Stroom voor ${label}"><strong data-expvalue="${id}"></strong></label>`).join('')}</div><div class="power-meter" id="power-meter"><i></i></div><p class="puzzle-help" id="capacity-label"></p><div class="consequence-cards" id="consequences"></div><label class="note-label" for="prediction">Wat verwacht je dat deze verdeling verandert?</label><textarea id="prediction" data-notes="${b.id}:prediction" placeholder="Je voorspelling vóór je de verdeling uitvoert.">${esc(state.notes[`${b.id}:prediction`]||'')}</textarea>${button('Schakel de verdeling in','runExperiment')}<div id="experiment-feedback"></div><p class="experiment-caption">Fictieve situatie · 100 energie-eenheden · geen verdeling bedient alle 140 gevraagde eenheden.</p>`;}
return `<p class="puzzle-help">Verplaats een deel van de rekening naar de veroorzaker. Vergelijk wie betaalt; let op wat er níét verandert.</p><label class="note-label">Aandeel afvalkosten op de rekening van NOVA: <strong id="cost-share"></strong></label><input type="range" min="0" max="100" step="25" value="${saved.share??0}" data-exp="share" aria-label="Aandeel afvalkosten bij NOVA" style="width:100%;accent-color:#648354"><div class="consequence-cards" id="consequences"></div><label class="note-label" for="prediction">Wat verwacht je dat verandert, en wat blijft gelijk?</label><textarea id="prediction" data-notes="${b.id}:prediction" placeholder="Voorspel wie meer betaalt en wat er gebeurt met de totale kosten.">${esc(state.notes[`${b.id}:prediction`]||'')}</textarea>${button('Voer deze afspraak uit','runExperiment')}<div id="experiment-feedback"></div><p class="experiment-caption">Rekenvoorbeeld: 100 telefoons, €100 productiekosten en €20 afvalkosten per telefoon. Het productievolume staat vast.</p>`;}
function expValues(){return Object.fromEntries([...document.querySelectorAll('[data-exp]')].map(e=>[e.dataset.exp,Number(e.value)]));}
function refreshExperiment(){const b=activeBeat;if(!b||b.type!=='experiment')return;const v=expValues();state.expValues[b.id]=v;persist();if(b.simulation==='electricity'){const sum=v.production+v.repair+v.emergency;document.querySelectorAll('[data-expvalue]').forEach(e=>e.textContent=v[e.dataset.expvalue]);$('#power-meter').classList.toggle('over',sum>100);$('#power-meter i').style.width=Math.min(100,sum)+'%';$('#capacity-label').textContent=`${sum} / 100 eenheden gebruikt${sum>100?' · deze verdeling kan niet worden uitgevoerd':''}`;$('#consequences').innerHTML=[['Productie',v.production,60,v.production<60?'De lancering loopt vertraging op.':'De productielijn blijft draaien.'],['Reparatie',v.repair,40,v.repair<40?'Een deel van de reparaties wacht.':'Alle geplande reparaties gaan door.'],['Noodklanten',v.emergency,40,v.emergency<40?'Noodtoestellen worden later geleverd.':'Noodklanten ontvangen hun toestellen.']].map(([label,n,d,text])=>`<article class="consequence-card ${n<d?'waiting':''}"><strong>${label} · ${n}/${d}</strong><span>${text}</span></article>`).join('');const run=document.querySelector('[data-act=runExperiment]');if(run)run.disabled=sum>100;}else{const company=10000+2000*v.share/100,others=2000*(1-v.share/100);$('#cost-share').textContent=v.share+'%';$('#consequences').innerHTML=`<article class="consequence-card"><strong>NOVA</strong>€ ${company.toLocaleString('nl-NL')}</article><article class="consequence-card ${others?'waiting':''}"><strong>De omgeving</strong>€ ${others.toLocaleString('nl-NL')}</article><article class="consequence-card"><strong>Totale kosten</strong>€ 12.000</article>`;}}
function runExperiment(){const b=activeBeat,v=expValues(),prediction=state.notes[`${b.id}:prediction`]?.trim();if(!prediction){notify('Noteer eerst kort wat je verwacht.');$('#prediction').focus();return;}if(b.simulation==='electricity'&&v.production+v.repair+v.emergency>100)return;state.trials[b.id]??=[];const trials=state.trials[b.id],signature=JSON.stringify(v);if(!trials.some(t=>t.signature===signature))trials.push({signature,values:v,prediction});persist();const contrast=b.simulation==='electricity'?trials.some(t=>t.values.production>=50)&&trials.some(t=>t.values.emergency>=30&&t.values.production<=30):trials.some(t=>t.values.share<=25)&&trials.some(t=>t.values.share>=75);$('#experiment-feedback').innerHTML=`<div class="small-feedback">${contrast?'Je hebt twee verschillende prioriteiten zichtbaar gemaakt. Leg nu uit wat de vergelijking laat zien.':b.simulation==='electricity'?'Probeer ook een plan dat noodklanten meer en productie minder stroom geeft, of andersom.':'Vergelijk een afspraak waarin NOVA weinig draagt met een waarin NOVA minstens 75% van de afvalkosten draagt.'}</div><p class="trial-record">${trials.length} verschillende proef${trials.length===1?'':'en'} bewaard.</p>${contrast?`<label class="note-label" for="experiment-interpretation">Welke afweging of verschuiving zie je? Wat verandert er niet vanzelf?</label><textarea id="experiment-interpretation" data-notes="${b.id}:interpretation" placeholder="Gebruik de twee proeven om het mechanisme te verklaren.">${esc(state.notes[`${b.id}:interpretation`]||'')}</textarea>${button('Bewaar mijn vergelijking','finishExperiment')}`:''}`;}
function finishExperiment(){const b=activeBeat,note=state.notes[`${b.id}:interpretation`]?.trim();if(!note){notify('Beschrijf eerst de vergelijking in je eigen woorden.');return;}const question=b.simulation==='electricity'?'Wat maakte het verschil tussen je plannen?':'Wat kun je uit de twee afspraken afleiden?',options=b.simulation==='electricity'?[['criterion','Een ander verdelingscriterium verschuift wie het tekort draagt.'],['capacity','Een ander criterium verandert hoeveel stroom de accu bevat.'],['neutral','De technisch uitvoerbare verdeling bepaalt automatisch wie voorrang hoort te krijgen.']]:[['distribution','De kosten verschuiven; zonder verdere verandering blijven volume en totale kosten gelijk.'],['damage','Het verplaatsen van de rekening bewijst dat de vervuiling meteen afneemt.'],['total','NOVA betaalt meer, dus de maatschappelijke kosten zijn in dit voorbeeld hoger.']];$('#experiment-feedback').innerHTML=`<p>${question}</p><div class="puzzle-cards">${options.map(([id,text])=>`<button class="puzzle-card" data-act="interpretExperiment" data-id="${id}">${text}</button>`).join('')}</div>`;}
function interpretExperiment(id){const correct=activeBeat.simulation==='electricity'?'criterion':'distribution';if(id===correct)collectBeat();else $('#experiment-feedback').insertAdjacentHTML('beforeend',`<div class="small-feedback retry">${esc(activeBeat.hint)} Vergelijk wat je daadwerkelijk hebt veranderd met wat in beide proeven gelijk bleef.</div>`);}
function readClue(id){const b=allBeats().find(b=>b.id===id);selectedClue=id;tray(b.clueTitle||b.title,`<p>${esc(b.explainAfter)}</p><label class="note-label" for="clue-note">Mijn eigen verband</label><textarea id="clue-note" data-notes="${b.id}" placeholder="Aan welk ander inzicht verbind je dit?">${esc(state.notes[b.id]||'')}</textarea>${button('Terug naar de kamer','closeTray')}`,'Een bewaarde aanwijzing');}
function npcPanel(){npcTopic=null;npcFollow=null;renderNPC();}
function renderNPC(){const n=npc(),topic=n.topics.find(t=>t.id===npcTopic),follow=topic?.followups?.find(f=>f.id===npcFollow);let body=`<div class="npc-line"><span class="npc-name">${esc(n.name)} · ${esc(n.role)}</span><p>${esc(follow?.answer||topic?.answer||n.opening)}</p></div>`;if(topic){body+=`<div class="npc-questions">${(topic.followups||[]).map(f=>button(esc(f.question),'npcFollow','btn-secondary',`data-id="${f.id}"`)).join('')}${button('Een andere vraag stellen','npcTopics','btn-secondary')}</div><button class="hint-toggle" data-act="saveNPC">Bewaar dit inzicht in mijn notities</button>`;}else body+=`<div class="npc-questions">${n.topics.map(t=>button(esc(t.question),'npcTopic','btn-secondary',`data-id="${t.id}"`)).join('')}</div>`;tray(`In gesprek met ${n.name}`,body,'Jij kiest wat je vraagt');}
function openPanel(title,body,kicker='Je onderzoek'){closeTray();panelContent.innerHTML=`<header class="panel-head"><div><p class="eyebrow">${esc(kicker)}</p><h2 id="panel-title" tabindex="-1">${esc(title)}</h2></div><button class="close" data-act="closePanel" aria-label="Sluiten">×</button></header><div class="panel-body">${body}</div>`;if(!panel.open)panel.showModal();panel.scrollTop=0;$('#panel-title').focus({preventScroll:true});}
function beginFinale(lesson=false){const current=inv();if(!lesson&&!investigated(state,current)){notify('Onderzoek eerst alle aanwijzingen.');return;}if(lesson&&book.chapters[0].investigations.some(i=>!state.rooms.includes(i.id))){notify('Rond eerst alle plekken van les 1 af.');return;}const finale=lesson?book.chapters[0].chapterFinale:current.finale;if(!finale){notify('Deze eindpuzzel wordt nog ontworpen.');return;}finalView={finale,key:lesson?'lesson-1':current.id,index:0,lesson,selectedEvidence:null};renderFinale();}
function renderFinale(feedback=''){const f=finalView,{finale,index,key}=f,slot=finale.slots[index],answer=state.finalAnswers[`${key}:${slot.id}`]||{},evidence=allBeats().filter(b=>state.beats.includes(b.id)&&(f.lesson||inv().beats.includes(b))),correct=slot.options.some(o=>o.id===answer.option&&o.correct)&&answer.evidence===slot.evidenceBeatId;const facts=finale.caseFacts||finale.facts||[];openPanel(f.lesson?'De eindpuzzel van les 1':'Breng de puzzelstukken samen.',`<section class="finale-sheet"><div class="causal-stepper">${finale.slots.map((s,n)=>`<span class="${n<index?'done':''}"></span>`).join('')}</div><p class="eyebrow">Verband ${index+1} / ${finale.slots.length} · een nieuwe situatie</p><p>${esc(finale.intro)}</p>${facts.length?`<details class="case-facts"><summary>De feiten van deze nieuwe situatie</summary>${facts.map(x=>`<p>${esc(typeof x==='string'?x:x.text||x.fact)}</p>`).join('')}</details>`:''}<h2>${esc(slot.label||slot.prompt)}</h2><div class="evidence-shelf">${evidence.map(b=>`<button class="evidence-token ${f.selectedEvidence===b.id?'selected':''}" data-act="chooseEvidence" data-id="${b.id}" data-clue="${b.id}" draggable="true">${esc(b.clueTitle||b.title)}</button>`).join('')}</div><button class="evidence-slot" data-drop-evidence="true" data-act="placeEvidence">${answer.evidence?`Bewijs: ${esc(allBeats().find(b=>b.id===answer.evidence)?.clueTitle||allBeats().find(b=>b.id===answer.evidence)?.title)}`:'Sleep hier de aanwijzing die dit verband onderbouwt, of klik eerst op een aanwijzing en dan hier.'}</button><p class="note-label">Welke verklaring volgt uit de situatie en jouw bewijs?</p><div class="puzzle-cards">${slot.options.map(o=>`<button class="puzzle-card ${answer.option===o.id?'selected':''}" data-act="finalOption" data-id="${o.id}">${esc(o.text)}</button>`).join('')}</div>${feedback?`<div class="small-feedback ${correct?'':'retry'}" aria-live="polite">${esc(feedback)}</div>`:''}<div class="panel-footer">${button('Controleer het verband','checkFinale','btn-secondary')}${button(index===finale.slots.length-1?'Maak de reconstructie af':'Volgend verband '+icon('arrow'),'nextFinal','btn-primary',correct?'':'disabled')}</div><p class="source-note">We beoordelen de verklaring en het bewijs. Over de precieze verdeling van belangen kunnen meerdere standpunten verdedigbaar zijn.</p></section>`,'Bewijsbord · kennis toepassen');}
function chooseEvidence(id){finalView.selectedEvidence=id;document.querySelectorAll('.evidence-token').forEach(e=>e.classList.toggle('selected',e.dataset.id===id));}
function placeEvidence(id=finalView.selectedEvidence){if(!id){notify('Kies eerst een gevonden aanwijzing.');return;}const f=finalView,s=f.finale.slots[f.index];state.finalAnswers[`${f.key}:${s.id}`]??={};state.finalAnswers[`${f.key}:${s.id}`].evidence=id;persist();renderFinale();}
function finalOption(id){const f=finalView,s=f.finale.slots[f.index];state.finalAnswers[`${f.key}:${s.id}`]??={};state.finalAnswers[`${f.key}:${s.id}`].option=id;persist();renderFinale();}
function checkFinal(){const f=finalView,s=f.finale.slots[f.index],a=state.finalAnswers[`${f.key}:${s.id}`]||{},o=s.options.find(o=>o.id===a.option);let feedback;if(!o)feedback='Kies een verklaring en verbind die aan een aanwijzing.';else if(a.evidence!==s.evidenceBeatId)feedback='Je verklaring moet door het juiste bewijs worden ondersteund. Kijk welk mechanisme jouw aanwijzing daadwerkelijk laat zien.';else feedback=o.feedback;renderFinale(feedback);}
function nextFinal(){const f=finalView,s=f.finale.slots[f.index],a=state.finalAnswers[`${f.key}:${s.id}`];if(!a||a.evidence!==s.evidenceBeatId||!s.options.some(o=>o.id===a.option&&o.correct))return;if(f.index<f.finale.slots.length-1){f.index++;f.selectedEvidence=null;renderFinale();return;}if(!checkFinale(state,f.finale,f.key))return;if(f.lesson){state.finalLesson=true;persist();sound();openPanel('Les 1: je hebt de verbanden gelegd.',`<div class="room-complete"><p class="eyebrow">Economie & systemen · nieuwe situatie onderzocht</p><h2>Je kijkt nu verder.</h2><p>${esc(f.finale.conclusion)}</p><p>Je aanwijzingen, proeven en notities blijven in je onderzoeksboek. Later kun je terugkomen om de verbanden opnieuw te oefenen.</p>${button('Bewaar mijn onderzoeksboek','export')}${button('Bekijk mijn route','route','btn-quiet')}</div><div class="lesson-info">Les 2 krijgt een eigen adventure rond menselijk gedrag en systeemdruk. Die route is nog in ontwikkeling.</div>`,'De eerste adventure afgerond');}else{try{finishRoom(state,inv());persist();sound();render();openPanel('Het verband wordt zichtbaar.',`<div class="room-complete"><p class="eyebrow">Reconstructie gelukt · +120 XP</p><h2>${esc(inv().title)}</h2><p>${esc(f.finale.conclusion)}</p>${button(state.room===5?'Naar de eindpuzzel van les 1':'Ga naar de volgende plek '+icon('arrow'),'nextRoom')}</div>`,'Onderbouwd met je aanwijzingen');}catch(e){notify(e.message);}}}
function nextRoom(){if(!state.rooms.includes(inv().id))return;if(state.room===5){beginFinale(true);return;}state.room++;actor={x:.5,y:.87};panel.close();persist();render();speak(npc().opening);}
function route(){openPanel('De adventure van les 1.',`<p>Volg de noodbeslissing naar de keten, de machine, de spelregels en de etalage. Je gereedschap en inzichten blijven bij je.</p><div class="room-map">${book.chapters[0].investigations.map((i,n)=>{const available=n===0||state.rooms.includes(book.chapters[0].investigations[n-1].id);return `<button class="map-room" data-act="goRoom" data-index="${n}" ${available?'':'disabled'}><img src="${rooms[n].image}" alt="${esc(rooms[n].name)}"><div><p class="eyebrow">${n+1} / 6 · ${state.rooms.includes(i.id)?'Verbanden gelegd':available?'Te onderzoeken':'Nog gesloten'}</p><h3>${esc(i.title)}</h3><p>${esc(rooms[n].name)} · ${i.beats.length} aanwijzingen</p></div></button>`;}).join('')}</div>${book.chapters[0].investigations.every(i=>state.rooms.includes(i.id))?button('De eindpuzzel van les 1','lessonFinal'):''}<details class="future-route"><summary>De volgende lessen</summary>${campaign.chapters.slice(1).map(ch=>`<article><h3>${esc(ch.title)}</h3><p>Een nieuwe adventure-route · in ontwikkeling.</p></article>`).join('')}</details>`,'Economie & systemen');}
function blockHTML(b){if(b.t==='text')return `${b.heading?`<h3>${esc(b.heading)}</h3>`:''}${clean(b.body||'')}`;if(b.t==='tabs')return b.items.map(x=>`<article class="concept-card"><h3>${esc(x.title)}</h3>${clean(x.body)}</article>`).join('');if(b.t==='list')return `<ul>${b.items.map(x=>`<li>${clean(x)}</li>`).join('')}</ul>`;if(b.t==='svg')return `<figure><div class="diagram">${clean(b.svg)}</div><figcaption>${esc(b.caption)}</figcaption></figure>`;if(b.t==='image')return `<figure><img src="assets/course/${encodeURIComponent(b.src.split('/').at(-1))}" alt="${esc(b.caption)}" loading="lazy"><figcaption>${esc(b.caption)}</figcaption></figure>`;if(b.t==='video')return `<h3>${esc(b.title)}</h3><a href="https://www.youtube.com/watch?v=${b.youtube}${b.start?`&t=${b.start}s`:''}" target="_blank" rel="noopener">Bekijk de oorspronkelijke cursusvideo ↗</a>`;if(b.t==='quiz')return `${clean(b.question)}<details><summary>Bekijk opties en toelichting</summary>${b.options.map(o=>`<p>${o.correct?'✓ ':''}${clean(o.text)}</p>`).join('')}<p>${clean(b.feedback)}</p></details>`;if(b.t==='match')return `${clean(b.question)}<details><summary>Bekijk de verbindingen</summary>${b.pairs.map(p=>`<p><strong>${esc(p.left)}</strong><br>${esc(p.right)}</p>`).join('')}</details>`;return '';}
function knowledge(){const chapters=course.lessons.map(l=>`<details><summary>${esc(l.title)}</summary>${l.blocks.filter(b=>b.t!=='continue').map(b=>`<section class="library-block source-body">${blockHTML(b)}</section>`).join('')}</details>`).join('');openPanel('Naslag, wanneer je die nodig hebt.',`<p class="muted">De oorspronkelijke cursus blijft hier beschikbaar. Het avontuur leert je via situaties, proeven en aanwijzingen.</p><div class="library">${chapters}</div>`,'Business Ethics · volledige oorspronkelijke inhoud');}
function settings(){openPanel('Mijn onderzoek bewaren.',`<p>Je voortgang, gereedschap, proeven en notities worden op dit apparaat bewaard.</p><div class="settings-list">${button('Download voortgang en onderzoeksboek','export','btn-secondary')}${button('Beloningsgeluid: '+(state.muted?'uit':'aan'),'sound','btn-secondary')}<label class="btn btn-secondary" for="import-progress">Open een opgeslagen onderzoek<input id="import-progress" type="file" accept="application/json,.json" class="sr-only"></label>${button('Een nieuw onderzoek beginnen','resetPrompt','btn-quiet')}</div><p class="source-note">Eerste speelbare versie van les 1. De latere adventure-routes worden nog ontworpen. Het leren wordt na technische en inhoudelijke controle ook met studenten onderzocht.</p><a class="research-link" href="research.html" target="_blank" rel="noopener">Bekijk de wetenschappelijke onderbouwing en het toetsplan ↗</a>`,'Instellingen');}
function exportSave(){const data={...state,exportedAt:new Date().toISOString()},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='nova-mijn-onderzoeksboek.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);notify('Je onderzoeksboek is gedownload.');}
function help(){openPanel('Zo onderzoek je de wereld.',`<div class="orientation-cards"><article><h3>Vliegen en kijken</h3><p>Bestuur je onderzoeksdrone door te klikken of met WASD / pijltjestoetsen. Klik op een voorwerp: je drone vliegt erheen.</p></article><article><h3>Voorwerpen gebruiken</h3><p>Neem gereedschap mee. Klik erop in je inventaris en daarna op het voorwerp waarop je het wilt gebruiken.</p></article><article><h3>Vragen en proberen</h3><p>Klik op een persoon, of kies Praten, om vragen te stellen en door te vragen. Experimenteer, vergelijk gevolgen en bewaar jouw verklaring.</p></article><article><h3>De aanwijzingen verbinden</h3><p>Rechts staat je onderzoeksboek. Als je alles hebt onderzocht, kun je het bewijs combineren en een nieuwe situatie verklaren.</p></article></div>`,'Het leerlab van NOVA');}
const acts={start:()=>{state.started=true;persist();render();speak('De noodaccu kan niet iedereen bedienen. Zoek eerst de stroommeter op de werkbank.');},home:()=>{state.started=false;persist();render();},route,knowledge,settings,help,approach:b=>approach(b.dataset.id),approachTool:b=>approachTool(b.dataset.id),approachNPC,approachExtra:b=>approachExtra(b.dataset.id),sideAnswer:b=>{const o=activeSpot.options[Number(b.dataset.index)];renderExtra(o.feedback,o.correct);},saveSide,searchSpots:b=>{const shown=$('#walk-scene').classList.toggle('show-spots');b.setAttribute('aria-pressed',String(shown));b.textContent=shown?'Verberg zoekplekken':'Toon zoekplekken';},closeTray,closePanel:()=>panel.close(),takeTool:b=>{if(!state.tools.includes(b.dataset.id))state.tools.push(b.dataset.id);selectedTool=b.dataset.id;verb='use';persist();render();speak(`Ik heb de ${tools.find(t=>t.id===selectedTool).name.toLowerCase()} meegenomen. Nu kan ik hem gebruiken.`,'Jij');sound();},selectTool:b=>{selectedTool=b.dataset.id;verb='use';document.querySelectorAll('.pocket-item').forEach(e=>e.classList.toggle('active',e.dataset.id===selectedTool));document.querySelectorAll('.verb').forEach(e=>e.classList.toggle('active',e.dataset.verb===verb));speak(tools.find(t=>t.id===selectedTool).detail,'Gereedschap');},verb:b=>{verb=b.dataset.verb;document.querySelectorAll('.verb').forEach(e=>e.classList.toggle('active',e.dataset.verb===verb));},hint:()=>{$('#beat-hint').innerHTML=`<div class="tray-hint">${esc(activeBeat.hint)}</div>`;},inspect:b=>inspect(b.dataset.id),selectCard:b=>selectCard(b.dataset.id),placeCard:b=>placeCard(b.dataset.id),connect:b=>connect(b.dataset.id),addOrder:b=>addOrder(b.dataset.id),removeOrder:b=>{state.orders[activeBeat.id]?.splice(Number(b.dataset.index),1);persist();renderBeat();},build:b=>{state.selections[activeBeat.id]??=[];const a=state.selections[activeBeat.id],id=b.dataset.id;state.selections[activeBeat.id]=a.includes(id)?a.filter(x=>x!==id):[...a,id];persist();renderBeat();},checkBeat,decide:b=>decide(b.dataset.id),collectBeat,replayBeat:()=>{activeBeat.replay=true;renderBeat();},runExperiment,finishExperiment,interpretExperiment:b=>interpretExperiment(b.dataset.id),readClue:b=>readClue(b.dataset.id),npc:npcPanel,npcTopic:b=>{npcTopic=b.dataset.id;npcFollow=null;renderNPC();},npcFollow:b=>{npcFollow=b.dataset.id;renderNPC();},npcTopics:()=>{npcTopic=null;npcFollow=null;renderNPC();},saveNPC:()=>{const n=npc(),t=n.topics.find(t=>t.id===npcTopic),f=t?.followups?.find(x=>x.id===npcFollow),text=f?.answer||t?.answer;if(text){state.notes[inv().id]=(state.notes[inv().id]||'')+`\n${n.name}: ${text}`;persist();$('#field-notes').value=state.notes[inv().id];notify('Gespreksinzicht bewaard in je onderzoeksboek.');}},finale:()=>beginFinale(),lessonFinal:()=>beginFinale(true),chooseEvidence:b=>chooseEvidence(b.dataset.id),placeEvidence:()=>placeEvidence(),finalOption:b=>finalOption(b.dataset.id),checkFinale:checkFinal,nextFinal,nextRoom,goRoom:b=>{const n=Number(b.dataset.index);if(n>0&&!state.rooms.includes(book.chapters[0].investigations[n-1].id))return;state.room=n;state.started=true;actor={x:.5,y:.85};panel.close();persist();render();},export:exportSave,sound:()=>{state.muted=!state.muted;persist();sound();settings();},resetPrompt:()=>openPanel('Opnieuw beginnen?',`<p>Dit wist de huidige voortgang op dit apparaat. Download eerst je onderzoeksboek als je dit onderzoek wilt bewaren.</p>${button('Bewaren','export','btn-secondary')}${button('Wis en begin opnieuw','reset')}`),reset:()=>{state=fresh();state.tools=[];state.expValues={};persist();panel.close();render();}};
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(el){if(!el.disabled)acts[el.dataset.act]?.(el);return;}const scene=e.target.closest('#walk-scene');if(scene&&!e.target.closest('.interaction-tray')&&!panel.open){closeTray();const r=scene.getBoundingClientRect();walkTo((e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height);scene.focus({preventScroll:true});}});
document.addEventListener('input',e=>{if(e.target.dataset.notes){state.notes[e.target.dataset.notes]=e.target.value;persist();const s=$('#save-indicator');if(s)s.textContent='Opgeslagen.';}if(e.target.dataset.exp)refreshExperiment();});
document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-card],[data-clue]');if(!el)return;dragged={id:el.dataset.card||el.dataset.clue,clue:!!el.dataset.clue};e.dataTransfer.setData('text/plain',dragged.id);e.dataTransfer.effectAllowed='move';});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop],[data-orderdrop],[data-drop-evidence]'))e.preventDefault();});
document.addEventListener('drop',e=>{const target=e.target.closest('[data-drop],[data-orderdrop],[data-drop-evidence]');if(!target||!dragged)return;e.preventDefault();if(target.dataset.dropEvidence&&dragged.clue)placeEvidence(dragged.id);else if(target.dataset.drop&&activeBeat?.type==='sort'){activeCard=dragged.id;placeCard(target.dataset.drop);}else if(target.dataset.orderdrop&&activeBeat?.type==='order')addOrder(dragged.id);dragged=null;});
document.addEventListener('keydown',e=>{if(!state?.started||panel.open||e.target.closest('input,textarea,select,.interaction-tray')||activeBeat)return;const dir={ArrowLeft:[-1,0],a:[-1,0],ArrowRight:[1,0],d:[1,0],ArrowUp:[0,-1],w:[0,-1],ArrowDown:[0,1],s:[0,1]}[e.key];if(!dir)return;e.preventDefault();closeTray();walkTo(actor.x+dir[0]*.04,actor.y+dir[1]*.04);});
document.addEventListener('change',async e=>{if(e.target.id==='import-progress'){try{const file=e.target.files[0];if(!file||file.size>2e6)throw Error();const raw=JSON.parse(await file.text());if(raw.version!==2)throw Error();state=restore(raw,book);state.tools??=[];state.expValues??={};persist();panel.close();render();notify('Onderzoeksboek geopend.');}catch{notify('Dit is geen geldig onderzoeksboek voor deze adventure.');}}});
function frame(time){const dt=(time-lastFrame)/1000||0;lastFrame=time;if(goal&&state?.started&&!panel.open){const p=moveToward(actor,goal,dt);actor.facing=goal.x<actor.x?-1:1;actor={...actor,x:p.x,y:p.y};positionActor();if(p.arrived){goal=null;$('#player')?.classList.remove('walking');const cb=arrival;arrival=null;cb?.();}}requestAnimationFrame(frame);}
try{[course,campaign,book,extras]=await Promise.all(['course.json','campaign.json','playbook.json','room-extras.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('De adventure wordt klaargezet.');return r.json();}));book.chapters[0].investigations.forEach(i=>{const original=campaign.chapters[0].investigations.find(o=>o.id===i.id);i.title=original.title;i.mission=original.mission;});try{dialogues=await(await fetch('npc-dialogues.json')).json();}catch{}let raw;try{raw=JSON.parse(localStorage.getItem(KEY));}catch{}state=restore(raw,book);state.tools??=[];state.expValues??={};render();requestAnimationFrame(frame);}catch(e){app.innerHTML=`<main class="loading"><h2>De adventure wordt klaargezet.</h2><p>${esc(e.message)}</p><a href="./">Opnieuw openen</a></main>`;}


